import { motion, AnimatePresence } from "framer-motion";
import { useEffect, useState } from "react";

export default function App() {
  const [scrolled, setScrolled] = useState(false);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 50);
    window.addEventListener("scroll", onScroll);
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  useEffect(() => {
    const t = setTimeout(() => setLoading(false), 1600);
    return () => clearTimeout(t);
  }, []);

  const scrollTo = (id) =>
    document.getElementById(id)?.scrollIntoView({ behavior: "smooth" });

  return (
    <div className="min-h-screen text-gray-900 overflow-x-hidden">
      {/* Loader */}
      <AnimatePresence>
        {loading && (
          <motion.div
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 flex items-center justify-center bg-white"
          >
            <motion.h1
              initial={{ scale: 0 }}
              animate={{ scale: 1 }}
              className="text-5xl font-extrabold gradient-text"
            >
              Welcome, Nisha ✨
            </motion.h1>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Navbar */}
      <nav
        className={`fixed top-0 w-full z-40 transition-all ${
          scrolled
            ? "bg-white/80 backdrop-blur-xl shadow-lg py-3"
            : "bg-transparent py-6"
        }`}
      >
        <div className="max-w-6xl mx-auto px-6 flex justify-between items-center">
          <div
            onClick={() => window.scrollTo({ top: 0, behavior: "smooth" })}
            className="text-3xl font-extrabold gradient-text cursor-pointer"
          >
            &lt; Nisha /&gt;
          </div>
          <div className="hidden md:flex gap-8 font-semibold text-gray-600">
            {["about", "skills", "projects", "contact"].map((i) => (
              <button
                key={i}
                onClick={() => scrollTo(i)}
                className="hover:text-[#6b63ff] transition"
              >
                {i.toUpperCase()}
              </button>
            ))}
          </div>
        </div>
      </nav>

      {/* Hero */}
      <section
        id="about"
        className="min-h-screen flex items-center justify-center px-6 pt-28"
      >
        <div className="max-w-6xl w-full grid md:grid-cols-2 gap-16 items-center">
          <motion.div initial={{ y: 50, opacity: 0 }} animate={{ y: 0, opacity: 1 }}>
            <h1 className="text-5xl md:text-6xl font-extrabold mb-6">
              Hi, I’m <span className="gradient-text">Nisha</span> 👋
            </h1>
            <p className="text-xl text-gray-600 mb-8 max-w-xl">
              Creative Developer building immersive
              <span className="font-semibold text-[#6b63ff]">
                {" "}AR, 3D & AI platforms
              </span>
            </p>
            <div className="flex gap-4">
              <GlowButton onClick={() => scrollTo("contact")}>Contact Me</GlowButton>
              <OutlineButton onClick={() => scrollTo("projects")}>
                View Work
              </OutlineButton>
            </div>
          </motion.div>

          <motion.div
            initial={{ scale: 0.8, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            className="flex justify-center"
          >
            <div className="relative w-80 h-80 float">
              <div className="absolute inset-0 bg-[#6b63ff]/30 blur-3xl rounded-full" />
              <img
                src="/nishaa.png"
                alt="Nisha"
                className="relative z-10 w-full h-full rounded-full object-cover border-4 border-white shadow-2xl"
              />
            </div>
          </motion.div>
        </div>
      </section>

      {/* Skills */}
      <Section id="skills" title="What I Do" subtitle="Tech I use">
        <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
          {[
            "JavaScript",
            "React",
            "Three.js",
            "AR.js",
            "WebGL",
            "Node.js",
            "Blockly",
            "AWS",
          ].map((s) => (
            <motion.div
              key={s}
              whileHover={{ y: -10, scale: 1.05 }}
              className="glass p-6 rounded-2xl shadow-xl font-bold text-lg neon-hover"
            >
              {s}
            </motion.div>
          ))}
        </div>
      </Section>

      {/* Projects */}
      <Section
        id="projects"
        title="Projects"
        subtitle="Things I’ve built"
        dark
      >
        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
          <ProjectCard
            title="Block-based 3D Platform"
            desc="Scratch-like 3D + AI coding system"
            img="/project1.jpg"
            tech={["React", "Three.js", "AI"]}
          />
          <ProjectCard
            title="AR Web Experience"
            desc="Marker-based AR.js experience"
            img="/project2.jpg"
            tech={["AR.js", "WebXR"]}
          />
        </div>
      </Section>

      {/* Contact */}
      <Section
        id="contact"
        title="Contact Me"
        subtitle="Let’s build something cool"
      >
        <p className="text-lg mb-2">📍 Gandhinagar, India</p>
        <p className="text-lg mb-6">📧 nishchaudhari4800@gmail.com</p>
        <div className="flex justify-center gap-4">
          <SocialButton href="mailto:nishchaudhari4800@gmail.com" icon="📧" />
          <SocialButton href="https://github.com/ErNisha4800" icon="🐙" />
        </div>
      </Section>

      <footer className="py-6 text-center text-gray-500">
        Made with ❤️ by Nisha
      </footer>
    </div>
  );
}

/* ---------- Components ---------- */

function Section({ id, title, subtitle, children, dark }) {
  return (
    <section
      id={id}
      className={`py-28 px-6 ${
        dark
          ? "bg-gradient-to-br from-[#0f0c29] via-[#302b63] to-[#24243e] text-white"
          : ""
      }`}
    >
      <div className="max-w-6xl mx-auto text-center">
        <h2 className="text-4xl md:text-5xl font-extrabold mb-3 gradient-text">
          {title}
        </h2>
        <p className="opacity-70 mb-14">{subtitle}</p>
        {children}
      </div>
    </section>
  );
}

function GlowButton({ children, ...props }) {
  return (
    <button
      {...props}
      className="px-8 py-3 rounded-xl font-bold text-white
      bg-gradient-to-r from-[#6b63ff] to-pink-500
      hover:scale-110 transition shadow-lg"
    >
      {children}
    </button>
  );
}

function OutlineButton({ children, ...props }) {
  return (
    <button
      {...props}
      className="px-8 py-3 rounded-xl font-bold border bg-white/80
      hover:bg-[#6b63ff] hover:text-white hover:scale-110 transition"
    >
      {children}
    </button>
  );
}

function SocialButton({ href, icon }) {
  return (
    <a
      href={href}
      target="_blank"
      rel="noreferrer"
      className="w-12 h-12 flex items-center justify-center
      bg-white rounded-full shadow text-2xl
      hover:bg-[#6b63ff] hover:text-white hover:-translate-y-1 transition"
    >
      {icon}
    </a>
  );
}

function ProjectCard({ title, desc, img, tech }) {
  return (
    <motion.div
      whileHover={{ y: -12 }}
      className="glass rounded-2xl shadow-xl overflow-hidden"
    >
      <img src={img} alt={title} className="h-44 w-full object-cover" />
      <div className="p-6 text-left">
        <h3 className="text-xl font-bold mb-2">{title}</h3>
        <p className="text-sm text-gray-600 mb-4">{desc}</p>
        <div className="flex flex-wrap gap-2">
          {tech.map((t) => (
            <span
              key={t}
              className="text-xs px-3 py-1 rounded-full bg-[#6b63ff]/10 text-[#6b63ff]"
            >
              {t}
            </span>
          ))}
        </div>
      </div>
    </motion.div>
  );
}
